<?php
$couponEditId = (int)($couponEditId ?? 0);
$pageTitle = $couponEditId > 0 ? 'Edit Special Offer — RCS Admin' : 'Add Special Offer — RCS Admin';
$currentAdmPage = 'coupons';
include __DIR__ . '/layout.php';
?>
<div class="adm-pt"><?= $couponEditId > 0 ? 'Edit Special Offer' : 'Add Special Offer' ?></div>
<div class="fsec" style="max-width:820px">
  <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><div style="font-size:13px;color:var(--text2)">Create regular or customer order-based offers.</div><a class="btn btn-outline btn-sm" href="/admin/coupons">← Back to Special Offers</a></div>
  <div class="fg"><label>Offer Type *</label><select class="fi fi-sel" id="ec-offer-type" onchange="toggleOfferType()"><option value="regular">Regular Coupon</option><option value="order1">1st Order Offer</option><option value="order2">2nd Order Offer</option><option value="order3">3rd Order Offer</option></select></div>
  <div class="fg"><label>Coupon Code *</label><input class="fi" id="ec-code" placeholder="FIRST10" oninput="this.value=this.value.toUpperCase();setLanding(this.value.trim())" style="text-transform:uppercase;font-family:var(--fn);font-weight:700;letter-spacing:1px"></div>
  <div class="fg"><label>Description</label><input class="fi" id="ec-desc" placeholder="10% off on first order"></div>
  <div class="f2"><div class="fg"><label>Discount Type</label><select class="fi fi-sel" id="ec-type" onchange="toggleDiscountValue()"><option value="percent">Percentage (%)</option><option value="flat">Flat Amount (₹)</option><option value="free_shipping">Free Shipping</option></select></div><div class="fg" id="ec-value-wrap"><label>Discount Value *</label><input type="number" class="fi" id="ec-val" placeholder="10"></div></div>
  <div class="f2"><div class="fg" id="ec-min-wrap"><label>Min Order (₹)</label><input type="number" class="fi" id="ec-min" placeholder="0"></div><div class="fg"><label id="ec-uses-label">Max Uses (0 = unlimited)</label><input type="number" class="fi" id="ec-uses" placeholder="0"></div></div>
  <div class="f2"><div class="fg"><label>Coupon Scope</label><select class="fi fi-sel" id="ec-scope" onchange="toggleCouponScope(this.value)"><option value="all">All Products</option><option value="category">Specific Category</option></select></div><div class="fg" id="ec-cat-wrap" style="display:none"><label>Category *</label><select class="fi fi-sel" id="ec-category" onchange="loadCouponProducts()"><option value="">Select category</option></select></div></div>
  <div class="fg" id="ec-products-wrap" style="display:none"><label>Products *</label><details class="coupon-product-picker"><summary id="couponProductSummary">Select products</summary><div id="couponProductOptions" class="coupon-product-options"></div></details><small>Select one or more products from the chosen category.</small></div>
  <div class="f2"><label class="fg"><span>Campaign Popup</span><span class="fi" style="display:flex;align-items:center;gap:9px"><input type="checkbox" id="ec-popup-enabled"> Show popup on website</span></label><div class="fg"><label>Offer Banner Image (JPG/PNG/WEBP)</label><input class="fi" type="file" id="ec-popup-image" accept="image/jpeg,image/png,image/webp"><small id="ec-popup-current"></small></div></div>
  <div class="fg"><label>Offer Link</label><input class="fi" id="ec-offer-link" placeholder="/offers/OFFERCODE"></div>
  <div class="fg" id="ec-landing-wrap" style="display:none"><label>Discounted Products Page</label><div style="display:flex;gap:8px"><input class="fi" id="ec-landing-url" readonly><a class="btn btn-outline btn-sm" id="ec-landing-open" target="_blank" rel="noopener">Open</a></div></div>
  <div class="f2" id="ec-dates-wrap"><div class="fg"><label>Valid From</label><input type="date" class="fi" id="ec-from"></div><div class="fg"><label>Valid Until</label><input type="date" class="fi" id="ec-to"></div></div>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="btn btn-blue btn-sm" id="couponSaveBtn" onclick="saveCoupon()"><?= $couponEditId > 0 ? 'Update Special Offer' : 'Save Special Offer' ?></button><a class="btn btn-outline btn-sm" href="/admin/coupons">Cancel</a></div>
</div>
<script>
const CSRF = '<?= htmlspecialchars($csrf??'') ?>';
const COUPON_EDIT_ID = <?= (int)$couponEditId ?>;
let editCouponId = COUPON_EDIT_ID;
let allCouponProducts=[]; let selectedCouponProducts=new Set();
function escH(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function toast(msg,type='info'){const w=document.getElementById('tw');const t=document.createElement('div');t.className='toast '+type;t.textContent=msg;w.appendChild(t);requestAnimationFrame(()=>requestAnimationFrame(()=>t.classList.add('show')));setTimeout(()=>{t.classList.remove('show');setTimeout(()=>t.remove(),300);},2800);}
async function loadCouponCategories() { const res = await fetch('/admin/api/categories').then(r=>r.json()); const cats = res.categories || []; document.getElementById('ec-category').innerHTML = `<option value="">Select category</option>` + cats.map(c => `<option value="${c.id}">${escH(c.name)}</option>`).join(''); }
async function ensureCouponProducts(){if(allCouponProducts.length)return;const r=await fetch('/admin/api/products').then(r=>r.json());allCouponProducts=r.products||[];}
async function loadCouponProducts(){await ensureCouponProducts();const cat=Number(document.getElementById('ec-category').value||0),box=document.getElementById('couponProductOptions');const rows=allCouponProducts.filter(p=>Number(p.category_id)===cat);box.innerHTML=rows.map(p=>`<label><input type="checkbox" value="${p.id}" ${selectedCouponProducts.has(Number(p.id))?'checked':''} onchange="syncProductSelection()"> <span>${escH(p.name)}</span></label>`).join('')||'<small>No products found in this category.</small>';syncProductSelection();}
function syncProductSelection(){selectedCouponProducts=new Set([...document.querySelectorAll('#couponProductOptions input:checked')].map(el=>Number(el.value)));document.getElementById('couponProductSummary').textContent=selectedCouponProducts.size?`${selectedCouponProducts.size} product(s) selected`:'Select products';}
function toggleCouponScope(scope) { const scoped=scope==='category';document.getElementById('ec-cat-wrap').style.display=scoped?'':'none';document.getElementById('ec-products-wrap').style.display=scoped?'':'none';if(scoped)loadCouponProducts(); }
function toggleDiscountValue(){const free=document.getElementById('ec-type').value==='free_shipping';document.getElementById('ec-value-wrap').style.display=free?'none':'';if(free)document.getElementById('ec-val').value='0';}
function toggleOfferType(){const type=document.getElementById('ec-offer-type').value,regular=type==='regular';document.getElementById('ec-min-wrap').style.display=regular?'':'none';document.getElementById('ec-dates-wrap').style.display=regular?'':'none';document.getElementById('ec-uses-label').textContent=regular?'Max Uses (0 = unlimited)':`Valid on ${type.slice(-1)}${type==='order1'?'st':type==='order2'?'nd':'rd'} Order`; }
function setLanding(code){const wrap=document.getElementById('ec-landing-wrap'),url=code?`${location.origin}/offers/${encodeURIComponent(code)}`:'';wrap.style.display=url?'':'none';document.getElementById('ec-landing-url').value=url;document.getElementById('ec-landing-open').href=url;}
async function fillCoupon(c){ editCouponId=Number(c.id||COUPON_EDIT_ID||0); document.getElementById('ec-offer-type').value=c.offer_type||'regular';toggleOfferType();document.getElementById('ec-code').value=c.code||''; document.getElementById('ec-desc').value=c.description||''; document.getElementById('ec-type').value=c.discount_type||'percent';toggleDiscountValue(); document.getElementById('ec-val').value=Number(c.discount_value||0)||''; document.getElementById('ec-min').value=Number(c.min_order_amount||0)||''; document.getElementById('ec-uses').value=Number(c.max_uses||0)||''; const scope=(c.scope_type||'all')==='category'?'category':'all'; document.getElementById('ec-scope').value=scope; document.getElementById('ec-category').value=c.category_id||''; selectedCouponProducts=new Set((c.product_ids||[]).map(Number));document.getElementById('ec-popup-enabled').checked=Number(c.popup_enabled||0)===1;document.getElementById('ec-offer-link').value=c.offer_link||'';document.getElementById('ec-popup-current').textContent=c.popup_image?'Current image is configured.':''; toggleCouponScope(scope);await loadCouponProducts();setLanding(c.code||''); document.getElementById('ec-from').value=c.valid_from?String(c.valid_from).slice(0,10):''; document.getElementById('ec-to').value=c.valid_until?String(c.valid_until).slice(0,10):''; }
async function loadForEdit(){ await loadCouponCategories(); if(!COUPON_EDIT_ID){ await fillCoupon({}); return; } const res=await fetch('/admin/api/coupons').then(r=>r.json()); const coupon=(res.coupons||[]).find(c=>Number(c.id)===COUPON_EDIT_ID); if(!coupon){ toast('Coupon not found','error'); return; } await fillCoupon(coupon); }
async function saveCoupon() { const code=document.getElementById('ec-code').value.trim().toUpperCase(); const val=parseFloat(document.getElementById('ec-val').value); const scopeType=document.getElementById('ec-scope').value; const categoryId=parseInt(document.getElementById('ec-category').value||'0',10); syncProductSelection();if(!code||(!val&&document.getElementById('ec-type').value!=='free_shipping')){toast('Code and value required','error');return;} if(scopeType==='category'&&(!categoryId||!selectedCouponProducts.size)){toast('Select a category and at least one product','error');return;} const payload={offer_type:document.getElementById('ec-offer-type').value,offer_link:document.getElementById('ec-offer-link').value.trim(),code,description:document.getElementById('ec-desc').value.trim(),discount_type:document.getElementById('ec-type').value,discount_value:val,min_order_amount:parseFloat(document.getElementById('ec-min').value)||0,max_uses:parseInt(document.getElementById('ec-uses').value)||0,scope_type:scopeType,category_id:scopeType==='category'?categoryId:null,product_ids:[...selectedCouponProducts],popup_enabled:document.getElementById('ec-popup-enabled').checked,valid_from:document.getElementById('ec-from').value||null,valid_until:document.getElementById('ec-to').value||null}; const url=editCouponId?`/admin/api/coupons/${editCouponId}`:'/admin/api/coupons'; const method=editCouponId?'PUT':'POST'; const btn=document.getElementById('couponSaveBtn'); btn.disabled=true; btn.textContent='Saving...'; try{ const res=await fetch(url,{method,headers:{'Content-Type':'application/json','X-CSRF-TOKEN':CSRF},body:JSON.stringify(payload)}).then(r=>r.json()); if(!res.ok){toast(res.msg||'Failed','error');return;}const id=Number(res.id||editCouponId),file=document.getElementById('ec-popup-image').files[0];if(file){const fd=new FormData();fd.append('image',file);const upload=await fetch(`/admin/api/coupons/${id}/popup-image`,{method:'POST',headers:{'X-CSRF-TOKEN':CSRF},body:fd}).then(r=>r.json());if(!upload.ok){toast(upload.msg||'Coupon saved, but image upload failed','error');return;}}toast(editCouponId?'Coupon updated!':'Coupon created!','success'); window.location.href='/admin/coupons'; } finally{ btn.disabled=false; btn.textContent=COUPON_EDIT_ID?'Update Special Offer':'Save Special Offer'; } }
loadForEdit();
</script>
    </div></div></div>
</body></html>
